insert into Confirmations (user_id, time_stamp, action) values (''7'', ''2021-06-14 13:59:27'', ''confirmed'');
insert into Confirmations (user_id, time_stamp, action) values (''2'', ''2021-01-22 00:00:00'', ''confirmed'');
