insert into Sales (sale_id, customer_id, price) values (''2'', ''1'', ''354'');
insert into Sales (sale_id, customer_id, price) values (''3'', ''3'', ''988'');
insert into Sales (sale_id, customer_id, price) values (''4'', ''3'', ''856'');', '# Write your MySQL query statement below', 'Salesperson(salesperson_id), Customer(customer_id), Sales(sale_id)', '', 1, NOW(), NOW()),
(214, '整理奥运表', '表: Olympic

